import { Buffer } from 'node:buffer';

/** Builds small original fixtures that exercise file previews without shipping third-party assets. */
export function createGcodeFixture(shape: 'cube' | 'bracket' | 'strip'): Buffer {
  const lines = [
    ';FLAVOR:Marlin', ';Generated by Tessera Mock', ';TIME:2400',
    ';Filament used: 1.8m', 'G28', 'G90', 'M83', 'M104 S205', 'M140 S60',
  ];
  const width = shape === 'bracket' ? 80 : shape === 'strip' ? 110 : 45;
  for (let layer = 1; layer <= (shape === 'strip' ? 8 : 28); layer++) {
    const z = (layer * 0.2).toFixed(2);
    lines.push(`;LAYER:${layer - 1}`, `G1 Z${z} F600`, ';TYPE:WALL-OUTER');
    lines.push(`G1 X20 Y20 F3600`, `G1 X${20 + width} Y20 E1.2 F1800`);
    lines.push(`G1 X${20 + width} Y${20 + width / 2} E1.2`, `G1 X20 Y${20 + width / 2} E1.2`);
    lines.push(';TYPE:FILL', `G1 X${20 + width} Y${20 + width / 2} E0.7 F2700`);
  }
  lines.push('M104 S0', 'M140 S0');
  return Buffer.from(`${lines.join('\n')}\n`);
}

/** Returns a standalone thumbnail; the HTTP adapter serves it as an image. */
export function createThumbnail(label: string, color: string): Buffer {
  return Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><rect width="160" height="120" fill="#17232c"/><path d="M30 80 80 96 130 80 80 64Z" fill="${color}"/><path d="M30 80V44L80 60v36Z" fill="${color}" opacity=".7"/><path d="M80 60 130 44v36L80 96Z" fill="${color}" opacity=".85"/><text x="80" y="112" fill="white" text-anchor="middle" font-size="11" font-family="sans-serif">${label}</text></svg>`);
}

